//! Skill system integration — registers skills and grants XP on actions.
//!
//! Uses `bevy_skills` for XP tracking, leveling, and skill checks.
//! Skills and their gather XP come from the baked professiondb, the same data
//! the gameserver grants XP from, so client and server never disagree.

use bevy::prelude::*;
use bevy_items::profession::{GatherInfo, ProfessionDb, get_profession_db, init_profession_db};
use bevy_skills::{BevySkillsPlugin, GrantXpMsg, LevelUpMsg, SkillDef, SkillId, SkillRegistry};

use super::player::Player;
use super::toast::Toast;

/// Generated by `node scripts/sync-professiondb.mjs` before each build.
const BAKED_PROFESSIONDB_JSON: &str = include_str!("../data/professiondb.json");

pub struct SkillsPlugin;

impl Plugin for SkillsPlugin {
    fn build(&self, app: &mut App) {
        app.add_plugins(BevySkillsPlugin);
        app.add_systems(Startup, load_baked_professiondb);
        app.add_systems(Startup, register_skills.after(load_baked_professiondb));
        app.add_systems(Update, notify_level_ups);
    }
}

/// Parse the baked professiondb and publish it globally so gather lookups
/// (`gather_info`) resolve for the whole app lifetime.
fn load_baked_professiondb() {
    if get_profession_db().is_some() {
        return;
    }
    match ProfessionDb::from_json(BAKED_PROFESSIONDB_JSON) {
        Ok(db) => {
            let professions = db.professions().len();
            let gathers = db.gather_len();
            let db_static: &'static ProfessionDb = Box::leak(Box::new(db));
            init_profession_db(db_static);
            info!(
                "[professiondb] loaded {professions} professions, {gathers} gather entries from baked professiondb.json"
            );
        }
        Err(e) => {
            warn!(
                "[professiondb] failed to parse baked professiondb.json: {e} — skills fall back to defaults"
            );
        }
    }
}

fn register_skills(mut registry: ResMut<SkillRegistry>) {
    if let Some(db) = get_profession_db() {
        for profession in db.professions() {
            registry.register(SkillDef {
                r#ref: profession.r#ref.clone(),
                name: profession.name.clone(),
                category: profession.category.clone(),
                icon: profession.emoji.clone(),
                xp_curve: None, // uses registry default (base=50, scaling=25, max=99)
            });
        }
        info!(
            "[skills] registered {} skills from professiondb",
            registry.len()
        );
        return;
    }

    for (r#ref, name) in [
        ("woodcutting", "Woodcutting"),
        ("mining", "Mining"),
        ("foraging", "Foraging"),
    ] {
        registry.register(SkillDef {
            r#ref: r#ref.into(),
            name: name.into(),
            category: "gathering".into(),
            icon: None,
            xp_curve: None,
        });
    }

    warn!(
        "[skills] professiondb unavailable — registered {} fallback skills",
        registry.len()
    );
}

/// Gather metadata (skill, required level, XP) for an item ref, straight from
/// professiondb. Returns `None` when the item is not a gatherable output.
pub fn gather_info(item_ref: &str) -> Option<&'static GatherInfo> {
    get_profession_db().and_then(|db| db.gather(item_ref))
}

/// Grant gathering XP to the local player for an item they collected.
///
/// Only used by offline/server-less flows — when connected, the server is
/// authoritative and XP arrives as `SkillXpGrant`.
pub fn grant_gather_xp(
    writer: &mut MessageWriter<GrantXpMsg>,
    player_entity: Entity,
    item_ref: &str,
    quantity: u32,
) {
    let Some(gather) = gather_info(item_ref) else {
        return;
    };
    if gather.xp_reward == 0 || quantity == 0 {
        return;
    }

    writer.write(GrantXpMsg {
        entity: player_entity,
        skill: SkillId::from_ref(&gather.skill_ref),
        amount: gather.xp_reward as u64 * quantity as u64,
    });
}

fn notify_level_ups(
    mut commands: Commands,
    mut level_ups: MessageReader<LevelUpMsg>,
    registry: Res<SkillRegistry>,
    player_q: Query<Entity, With<Player>>,
) {
    for event in level_ups.read() {
        // Only show toast for the local player
        if !player_q.contains(event.entity) {
            continue;
        }

        let skill_name = registry
            .get(event.skill)
            .map(|d| d.name.as_str())
            .unwrap_or("???");

        info!(
            "[skills] LEVEL UP! {} -> level {}",
            skill_name, event.new_level
        );

        commands.trigger(Toast::success(format!(
            "{} leveled up to {}!",
            skill_name, event.new_level
        )));
    }
}
